//#region src/services/profileService.ts
async function getProfile() {
	const id = await requireUserId();
	return unwrap(await supabase.from("profiles").select("*").eq("id", id).single(), "Unable to load your profile. Please try again.");
}
async function updateProfile(input) {
	const id = await requireUserId();
	return unwrap(await supabase.from("profiles").update(input).eq("id", id).select().single(), "We couldn't update your profile. Please try again.");
}
async function getPreferences() {
	const user_id = await requireUserId();
	const existing = await supabase.from("notification_preferences").select("*").eq("user_id", user_id).maybeSingle();
	if (existing.data) return existing.data;
	return unwrap(await supabase.from("notification_preferences").insert({ user_id }).select().single(), "Unable to load notification settings.");
}
async function updatePreferences(input) {
	const user_id = await requireUserId();
	return unwrap(await supabase.from("notification_preferences").update(input).eq("user_id", user_id).select().single(), "We couldn't update your notification settings. Please try again.");
}
async function changePassword(newPassword) {
	const { error } = await supabase.auth.updateUser({ password: newPassword });
	if (error) {
		console.error(error);
		throw new Error(error.message || "We couldn't change your password. Please try again.");
	}
}
